<?php use CmuLms\View;$title='Notifications';include __DIR__.'/../layout/header.php';?><section class="card"><h1>Notifications</h1><?php if(!$items):?><p>No notifications.</p><?php endif;?><?php foreach($items as $n):?><article class="card"><h3><?=View::e($n['title'])?></h3><p><?=View::e($n['body'])?></p><?php if(!empty($n['target_url'])):?><a class="btn" href="<?=View::e($n['target_url'])?>">Open related content</a><?php endif;?><?php if(!$n['read_at']):?><form method="post" action="?route=notification-read"><?=View::csrfField()?><input type="hidden" name="notification_id" value="<?=(int)$n['id']?>"><button>Mark as read</button></form><?php endif;?></article><?php endforeach;?></section><?php include __DIR__.'/../layout/footer.php';?>
